import { DomainError } from "./errors";

export class Product {
  public constructor(
    public readonly id: string,
    public readonly name: string,
    private stock: number,
  ) {
    if (!id.trim()) throw new DomainError("A product id is required.");
    if (!name.trim()) throw new DomainError("A product name is required.");
    if (!Number.isSafeInteger(stock) || stock < 0) {
      throw new DomainError("Product stock must be a non-negative integer.");
    }
  }

  public get availableStock(): number {
    return this.stock;
  }

  public reserve(quantity: number): void {
    this.assertQuantity(quantity);
    if (this.stock < quantity) {
      throw new DomainError(`Insufficient stock for product '${this.id}'.`);
    }
    this.stock -= quantity;
  }

  public release(quantity: number): void {
    this.assertQuantity(quantity);
    this.stock += quantity;
  }

  private assertQuantity(quantity: number): void {
    if (!Number.isSafeInteger(quantity) || quantity <= 0) {
      throw new DomainError("Quantity must be a positive integer.");
    }
  }
}

